import { isUndefined } from 'lodash-es';

import { useAnnotationsSelectionState } from './store/selectors.js';
import { WithId } from '../../../types/with-id.js';
import { MarkerInteractionState } from '../../annotations-atoms/types/marker.js';
import { buildMarkerState } from '../functions/build-marker-state.js';
import { Annotation } from '../types/annotations.js';

/**
 * Returns the current state of a given marker
 *
 * @param markerId -
 * @param trackNumber -
 * @param annotations -
 */
export function useMarkersBrightnessState(
  markerId: string,
  trackNumber: number,
  annotations: WithId<Annotation>[],
): MarkerInteractionState {
  const selection = useAnnotationsSelectionState();

  if (trackNumber !== selection.hoveredTrack) {
    return 'default';
  }

  const hoveredListItem = annotations.find(
    (annotation: WithId<Annotation>) =>
      annotation.id === selection.hoveredListItem,
  );

  return buildMarkerState(selection, markerId, !isUndefined(hoveredListItem));
}
